#include <string>

// Returns a reference to a string that lives in the caller's stack frame
// only until the function returns. EVERY caller hits UB on the next access.
const std::string& sniff_filename(int fd) {
    std::string buf;
    if (fd >= 0) buf = "/proc/self/fd/" + std::to_string(fd);
    else         buf = "<bad fd>";
    return buf;  // <-- UB: buf goes out of scope when we return.
}
